function ggClassScore(r) {
  return r.avg + r.s5 * 0.45 + r.s4 * 0.06 - Math.max(0, r.n - 25) * 0.08;
}
function ggPortalScore(r) {
  return (r.inn * r.inAvg) - (r.out * r.outAvg) + r.s5 * 40 + r.s4 * 8;
}
function recruitWhyClass(r) {
  if (r.s5 >= 4) return "The five-stars carry this class.";
  if (r.avg >= 91.4 && r.n <= 25) return "Smaller class, higher average.";
  if (r.n >= 33 && r.avg < 91) return "A lot of commits, a lower average.";
  if (r.s5 >= 2) return "More than one five-star.";
  return "Built from the average and the stars On3 posted.";
}
function recruitWhyPortal(r, net) {
  if (r.inAvg - r.outAvg >= 10) return "The players coming in are much higher rated than the ones leaving.";
  if (net < 0) return "More talent walked out than walked in.";
  if (r.s5 > 0) return "A five-star came in through the portal.";
  if (r.inn > r.out + 8) return "They added a lot more bodies than they lost.";
  return "Talent in, minus talent out.";
}

function teamBtn(name) {
  const safe = escHtml(name);
  return `<button type="button" class="commit-btn" data-team="${safe}" onclick="openCommits(this.getAttribute('data-team'))">${safe}</button>`;
}
function openCommits(team) {
  const list = (ON3_COMMITS[team] || []).slice().sort((a, b) => (b[2] || 0) - (a[2] || 0));
  const body = list.length
    ? `<div class="log-wrap"><table class="log"><thead><tr><th></th><th>Player</th><th>Pos</th><th>On3</th><th>School</th></tr></thead><tbody>${list.map((r, i) => `<tr><td>${i + 1}</td><td class="l">${escHtml(r[0])}</td><td>${escHtml(r[1])}</td><td>${r[2] == null ? "—" : Number(r[2]).toFixed(2)}</td><td class="l">${escHtml(r[3])}</td></tr>`).join("")}</tbody></table></div>`
    : `<p>No 2026 high school commit list for ${escHtml(team)} on this board.</p>`;
  $("#modal").innerHTML = `
    <div class="modal-head">
      <div>
        <div class="lbl">On3 · class of 2026</div>
        <h2 style="margin:4px 0">${escHtml(team)}</h2>
        <div class="subn">${list.length ? list.length + " commits" : "Commits"} · pulled September 22, 2026</div>
      </div>
      <button class="close" id="closeModal">Close</button>
    </div>
    ${body}`;
  const ov = document.getElementById("overlay");
  if (!ov) return;
  placeOverlay(ov);
  const closer = document.getElementById("closeModal");
  if (closer) closer.onclick = closeModal;
}
function renderRecruit() {
  if (!window.__recruitBound) {
    window.__recruitBound = true;
    $$("#recruitCats button").forEach((b) => b.addEventListener("click", () => {
      window.__recruitCat = b.dataset.cat;
      renderRecruit();
    }));
    const q = $("#recruitQ");
    if (q) q.addEventListener("input", () => renderRecruit());
    const board = document.getElementById("recruitBoard");
    if (board) board.addEventListener("click", (e) => {
      const tr = e.target.closest("tr[data-team]");
      if (tr) openCommits(tr.getAttribute("data-team"));
    });
    const confSel = document.getElementById("recruitConf");
    if (confSel) confSel.addEventListener("change", () => {
      window.__recruitConf = confSel.value;
      renderRecruit();
    });
  }
  const cat = window.__recruitCat || "on3class";
  $$("#recruitCats button").forEach((b) => b.classList.toggle("on", b.dataset.cat === cat));
  const q = (($("#recruitQ") && $("#recruitQ").value) || "").trim().toLowerCase();
  const confSel = document.getElementById("recruitConf");
  const conf = (confSel && confSel.value) || window.__recruitConf || "all";
  if (confSel && confSel.value !== conf) confSel.value = conf;
  const keep = (r) => (conf === "all" || r.conf === conf) && (!q || `${r.team} ${r.conf}`.toLowerCase().includes(q));
  const note = $("#recruitNote");
  let rows = "";
  if (cat === "on3class") {
    note.textContent = "On3’s 2026 team recruiting rankings, pulled September 22, 2026. The score is the number they published. We did not change it. Tap a school to see the commits.";
    rows = `<table class="log recruit-log"><thead><tr><th>#</th><th>Team</th><th>Conf</th><th>5 / 4 / 3</th><th>Commits</th><th>Avg</th><th>On3</th></tr></thead><tbody>`
      + ON3_CLASS.map((r, i) => ({ r, i })).filter((x) => keep(x.r)).map((x) => `<tr data-team="${x.r.team}"><td>${x.i + 1}</td><td class="l">${teamBtn(x.r.team)}</td><td>${x.r.conf}</td><td>${x.r.s5} / ${x.r.s4} / ${x.r.s3}</td><td>${x.r.n}</td><td>${x.r.avg.toFixed(2)}</td><td>${x.r.on3.toFixed(3)}</td></tr>`).join("")
      + `</tbody></table>`;
  } else if (cat === "on3portal") {
    note.textContent = "On3’s 2026 transfer portal team index, pulled September 22, 2026. Their index is how the portal class looks against that school’s own roster, not a raw talent total. Tap a school that is also in the class to see those high school commits.";
    rows = `<table class="log recruit-log"><thead><tr><th>#</th><th>Team</th><th>In</th><th>In avg</th><th>Out</th><th>Out avg</th><th>Stars in</th><th>On3</th></tr></thead><tbody>`
      + ON3_PORTAL.map((r, i) => ({ r, i })).filter((x) => keep(x.r)).map((x) => `<tr data-team="${x.r.team}"><td>${x.i + 1}</td><td class="l">${teamBtn(x.r.team)}</td><td>${x.r.inn}</td><td>${x.r.inAvg.toFixed(2)}</td><td>${x.r.out}</td><td>${x.r.outAvg.toFixed(2)}</td><td>${x.r.s5} / ${x.r.s4} / ${x.r.s3}</td><td>${x.r.on3}</td></tr>`).join("")
      + `</tbody></table>`;
  } else if (cat === "ggclass") {
    note.textContent = "Our class board. Same On3 schools, our order. Tap a school to see the commits.";
    const ranked = ON3_CLASS.map((r) => Object.assign({}, r, { gg: ggClassScore(r) })).sort((a, b) => b.gg - a.gg).map((r, i) => Object.assign(r, { rank: i + 1 }));
    const on3Rank = {};
    ON3_CLASS.forEach((r, i) => { on3Rank[r.team] = i + 1; });
    rows = `<table class="log recruit-log"><thead><tr><th>#</th><th>Team</th><th>On3</th><th>Avg</th><th>5-stars</th><th>Commits</th><th>Ours</th></tr></thead><tbody>`
      + ranked.filter((r) => keep(r)).map((r) => `<tr data-team="${r.team}"><td>${r.rank}</td><td class="l">${teamBtn(r.team)}</td><td>${on3Rank[r.team]}</td><td>${r.avg.toFixed(2)}</td><td>${r.s5}</td><td>${r.n}</td><td>${r.gg.toFixed(2)}</td></tr>`).join("")
      + `</tbody></table>`;
  } else {
    note.textContent = "Our portal board. Same On3 schools, our order. Tap a school that is also in the class to see those commits.";
    const ranked = ON3_PORTAL.map((r) => Object.assign({}, r, { gg: ggPortalScore(r) })).sort((a, b) => b.gg - a.gg).map((r, i) => Object.assign(r, { rank: i + 1 }));
    const on3Rank = {};
    ON3_PORTAL.forEach((r, i) => { on3Rank[r.team] = i + 1; });
    rows = `<table class="log recruit-log"><thead><tr><th>#</th><th>Team</th><th>On3</th><th>Net</th><th>In avg</th><th>Out avg</th><th>Ours</th></tr></thead><tbody>`
      + ranked.filter((r) => keep(r)).map((r) => `<tr data-team="${r.team}"><td>${r.rank}</td><td class="l">${teamBtn(r.team)}</td><td>${on3Rank[r.team]}</td><td>${r.inn - r.out > 0 ? "+" : ""}${r.inn - r.out}</td><td>${r.inAvg.toFixed(1)}</td><td>${r.outAvg.toFixed(1)}</td><td>${Math.round(r.gg)}</td></tr>`).join("")
      + `</tbody></table>`;
  }
  $("#recruitBoard").innerHTML = `<div class="log-wrap">${rows}</div>`;
}


